import re
from collections import defaultdict

import pandas as pd


def read_entity_text(entity_text_dir):
    """Read the entity text of MIMIC-IV ICD-10 generated by Entity-Coding"""
    return pd.concat(
        [
            pd.read_parquet(
                f"{entity_text_dir}/{split}.parquet",
                columns=["_id", "subject_id", "text"],
            )
            for split in ["train", "val", "test"]
        ]
    ).reset_index(drop=True)


def reformat_entity_text(input_text):
    """Group the entities of a note as {section: {entity_type: [entity_text, ...]}}"""
    grouped_entities = defaultdict(lambda: defaultdict(list))
    current_section = None
    entity_tag_pattern = re.compile(r"<([^>]+)>\s*(.*)")

    for line in input_text.strip().split("\n"):
        line = line.strip()
        if not line:
            continue

        # 1. Tagged entity: <type> text
        match = entity_tag_pattern.match(line)
        if match:
            entity_type, entity_text = match.groups()
            if not current_section:  # Entity appearing before any section header
                current_section = "Uncategorized"
            grouped_entities[current_section][entity_type].append(entity_text.strip())
            continue

        # 2. Implicit entity: Section: Entity Text (e.g., Allergy: Vancomycin)
        if ":" in line:
            section_maybe, entity_text = (part.strip() for part in line.split(":", 1))
            if "<" not in section_maybe and ">" not in section_maybe and entity_text:
                grouped_entities[section_maybe][section_maybe].append(entity_text)
                continue

        # 3. Otherwise, a section header
        current_section = line.rstrip(":").strip()

    return grouped_entities


def unique_entities_within_section(grouped_entities):
    """Ensure that entities within a section are unique"""
    for types_dict in grouped_entities.values():
        seen_entities = set()
        for entity_type, entities in types_dict.items():
            unique_entities = []
            for entity in entities:
                if entity not in seen_entities:
                    seen_entities.add(entity)
                    unique_entities.append(entity)
            types_dict[entity_type] = unique_entities
    return grouped_entities


def get_sections(grouped_entities, sections):
    """Keep only the specified sections"""
    return {
        section: grouped_entities[section]
        for section in sections
        if section in grouped_entities
    }


def get_types(grouped_entities, types, keep_n_entities=None):
    """Keep only the specified entity types (and at most `keep_n_entities` entities per type)"""
    filtered_entities = {}
    for section, types_dict in grouped_entities.items():
        new_section = {
            entity_type: entities
            if keep_n_entities is None
            else entities[:keep_n_entities]
            for entity_type, entities in types_dict.items()
            if entity_type in types
        }
        if new_section:
            filtered_entities[section] = new_section
    return filtered_entities


def entities_to_markdown(grouped_entities):
    """Convert grouped entities to markdown: # section, ## entity type, - entity"""
    markdown_output = []
    for section, types_dict in grouped_entities.items():
        if not types_dict:
            continue
        markdown_output.append(f"# {section}")
        for entity_type, entities in types_dict.items():
            if not entities:
                continue
            markdown_output.append(f"## {entity_type}")
            markdown_output.extend(f"- {entity}" for entity in entities)
    return "\n".join(markdown_output)


def format_entity_text(df, sections, types, keep_n_entities=None):
    """Keep the specified sections and entity types of each note, convert them to markdown, and drop empty notes"""

    def format_text(text):
        entities = unique_entities_within_section(reformat_entity_text(text))
        entities = get_types(get_sections(entities, sections), types, keep_n_entities)
        return entities_to_markdown(entities)

    df["text"] = df["text"].apply(format_text)
    df = df[df["text"].str.strip() != ""].reset_index(drop=True)
    df["num_words"] = df["text"].apply(lambda text: len(text.split()))
    return df
